def extract_hash(path: str) -> str | None:
    match = HASH_PATTERN.search(path)
    return match.group(1).lower() if match else None


def extract_suite(path: str) -> str:
    name = Path(path).name
    match = SUITE_PATTERN.match(name)
    if match:
        return match.group(1)
    stem = Path(path).stem
    if stem.startswith("results-"):
        return stem[len("results-") :]
    return stem


def git_full_hash(short_hash: str) -> str | None:
    try:
        result = subprocess.run(
            ["git", "rev-parse", "--verify", "--quiet", f"{short_hash}^{{commit}}"],
            capture_output=True,
            text=True,
            check=True,
        )
        full = result.stdout.strip()
        return full or None
    except subprocess.CalledProcessError:
        return None


def git_historical_order(short_hashes: list[str]) -> dict[str, int]:
    """Map each short hash to its position in git ancestry (older first)."""
    short_to_full: dict[str, str] = {}
    for short_hash in short_hashes:
        if short_hash in short_to_full:
            continue
        full = git_full_hash(short_hash)
        if full is not None:
            short_to_full[short_hash] = full

    if not short_to_full:
        return {}

    unique_full = list(dict.fromkeys(short_to_full.values()))
    try:
        result = subprocess.run(
            ["git", "rev-list", "--reverse", "--topo-order", *unique_full, "--"],
            capture_output=True,
            text=True,
            check=True,
        )
    except subprocess.CalledProcessError:
        return {}

    position = {
        line.strip(): index
        for index, line in enumerate(result.stdout.splitlines())
        if line.strip()
    }
    return {
        short: position[full]
        for short, full in short_to_full.items()
        if full in position
    }


def order_csv_files(filenames: list[str]) -> list[str]:
    hashed: list[tuple[str, str, int]] = []
    unhashed: list[tuple[str, int]] = []

    for index, filename in enumerate(filenames):
        short_hash = extract_hash(filename)
        if short_hash is not None:
            hashed.append((filename, short_hash, index))
        else:
            unhashed.append((filename, index))

    if not hashed:
        return list(filenames)

    order = git_historical_order([short_hash for _, short_hash, _ in hashed])

    with_git: list[tuple[str, int, int]] = []
    without_git: list[tuple[str, int]] = []

    for filename, short_hash, index in hashed:
        position = order.get(short_hash)
        if position is not None:
            with_git.append((filename, position, index))
        else:
            without_git.append((filename, index))

    with_git.sort(key=lambda item: (item[1], item[2]))
    without_git.sort(key=lambda item: item[1])

    ordered_hashed = [filename for filename, _, _ in with_git]
    ordered_hashed.extend(filename for filename, _ in without_git)
    ordered_unhashed = [filename for filename, _ in sorted(unhashed, key=lambda item: item[1])]

    return ordered_hashed + ordered_unhashed


def file_label(path: str) -> str:
    short_hash = extract_hash(path)
    if short_hash is not None:
        return short_hash
    stem = Path(path).stem
    if stem.startswith("results-"):
        return stem[len("results-") :]
    return stem


def measurement_label(name: str) -> str:
    if name.startswith("All."):
        return name[4:]
    return name


def plot_title(suite: str, name: str) -> str:
    return f"{suite}/{measurement_label(name)}"


def read_csv(path: str) -> dict[str, tuple[float, float]]:
    measurements: dict[str, tuple[float, float]] = {}
    with open(path, newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        for row in reader:
            name = row["Name"].strip()
            mean_ps = float(row["Mean (ps)"].strip())
            stdev2_ps = float(row["2*Stdev (ps)"].strip())
            measurements[name] = (mean_ps, stdev2_ps)
    return measurements


def make_plot_spec(
    plot_id: str,
    search_title: str,
    labels: list[str],
    means_ms: list[float],
    errors_ms: list[float],
) -> dict:
    # Use integer x positions and ticktext for labels. Plotly otherwise treats
    # git hashes that look like scientific notation (e.g. "376566e3") as numbers.
    x_values = list(range(len(labels)))
    return {
        "id": plot_id,
        "searchTitle": search_title,
        "data": [
            {
                "type": "scatter",
                "mode": "lines+markers",
                "x": x_values,
                "y": means_ms,
                "text": labels,
                "error_y": {
                    "type": "data",
                    "array": errors_ms,
                    "visible": True,
                },
                "hovertemplate": "%{text}<br>%{y:.4g} ms<extra></extra>",
                "showlegend": False,
            }
        ],
        "layout": {
            "yaxis": {
                "title": {"text": "Time (ms)"},
                "rangemode": "tozero",
                "autorange": True,
            },
            "xaxis": {
                "type": "linear",
                "tickmode": "array",
                "tickvals": x_values,
                "ticktext": labels,
                "dtick": 1,
                "tickangle": -90,
                "automargin": True,
            },
            "autosize": True,
            "margin": {"l": 60, "r": 30, "t": 20, "b": 120},
        },
    }


def build_html(plot_specs: list[dict], page_title: str) -> str:
    plot_blocks: list[str] = []

    for index, spec in enumerate(plot_specs):
        escaped_title = html.escape(spec["searchTitle"])
        plot_blocks.append(
            f'<div class="benchmark-plot" id="container-{index}">'
            f'<h2 class="plot-title">{escaped_title}</h2>'
            f'<div id="{spec["id"]}" class="plotly-chart"></div></div>'
        )

    specs_json = json.dumps(plot_specs).replace("</", "<\\/")
    plots_html = "\n".join(plot_blocks)
    plotly_js = get_plotly_js()
    escaped_page_title = html.escape(page_title, quote=True)

    return f"""<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>{escaped_page_title}</title>
  <style>
    body {{
      font-family: sans-serif;
      margin: 0;
      padding: 24px 0 48px;
    }}
    #search-container {{
      width: 80%;
      max-width: 960px;
      margin: 0 auto 24px;
    }}
    #search-box {{
      display: block;
      width: 100%;
      padding: 10px 12px;
      font-size: 16px;
      box-sizing: border-box;
    }}
    #search-box.invalid {{
      color: red;
    }}
    #search-error {{
      display: none;
      margin-top: 6px;
      color: red;
      font-size: 14px;
    }}
    #search-error.visible {{
      display: block;
    }}
    .benchmark-plot {{
      width: 80%;
      margin: 0 auto 32px;
    }}
    .plot-title {{
      text-align: center;
      font-size: 17px;
      font-weight: normal;
      margin: 0 0 4px;
      user-select: text;
    }}
    .plotly-chart {{
      width: 100%;
      min-height: 450px;
    }}
  </style>
</head>
<body>
  <div id="search-container">
    <input id="search-box" type="search" placeholder="Search by plot title (regex)">
    <div id="search-error">Invalid regex</div>
  </div>
  <div id="plots">
{plots_html}
  </div>
  <script>{plotly_js}</script>
  <script id="plot-specs" type="application/json">{specs_json}</script>
  <script>
    const specs = JSON.parse(document.getElementById("plot-specs").textContent);
    for (const spec of specs) {{
      Plotly.newPlot(
        spec.id,
        spec.data,
        spec.layout,
        {{responsive: true, displayModeBar: true}}
      );
    }}

    function compileSearchRegex(query) {{
      if (!query) {{
        return {{regex: null, invalid: false}};
      }}
      try {{
        return {{regex: new RegExp(query, "i"), invalid: false}};
      }} catch (error) {{
        return {{regex: null, invalid: true}};
      }}
    }}

    const searchBox = document.getElementById("search-box");
    const searchError = document.getElementById("search-error");
    searchBox.addEventListener("input", function () {{
      const query = this.value.trim();
      const {{regex, invalid}} = compileSearchRegex(query);

      searchBox.classList.toggle("invalid", invalid);
      searchError.classList.toggle("visible", invalid);

      specs.forEach(function (spec, index) {{
        const container = document.getElementById("container-" + index);
        if (invalid) {{
          container.style.display = "none";
        }} else if (!regex) {{
          container.style.display = "block";
        }} else {{
          container.style.display = regex.test(spec.searchTitle) ? "block" : "none";
        }}
      }});
    }});
  </script>
</body>
</html>
"""


def open_in_browser(path: Path) -> None:
    system = platform.system()
    if system == "Darwin":
        subprocess.run(["open", str(path)], check=False)
    elif system == "Linux":
        subprocess.run(["xdg-open", str(path)], check=False)
    else:
        print(f"Open {path} in your browser.", file=sys.stderr)


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Visualize Dhall benchmark CSV results as an interactive HTML report."
    )
    parser.add_argument(
        "csv_files",
        nargs="+",
        help="Benchmark CSV files (Name, Mean (ps), 2*Stdev (ps))",
    )
    args = parser.parse_args()

    ordered_files = order_csv_files(args.csv_files)
    datasets = {path: read_csv(path) for path in ordered_files}

    plot_keys: set[tuple[str, str]] = set()
    for path, measurements in datasets.items():
        suite = extract_suite(path)
        for name in measurements:
            plot_keys.add((suite, name))

    sorted_plot_keys = sorted(plot_keys, key=lambda item: plot_title(item[0], item[1]))

    plot_specs: list[dict] = []
    for index, (suite, name) in enumerate(sorted_plot_keys):
        title = plot_title(suite, name)
        labels: list[str] = []
        means_ms: list[float] = []
        errors_ms: list[float] = []

        for path in ordered_files:
            if extract_suite(path) != suite or name not in datasets[path]:
                continue
            mean_ps, stdev2_ps = datasets[path][name]
            labels.append(file_label(path))
            means_ms.append(mean_ps * PS_TO_MS)
            errors_ms.append(stdev2_ps * PS_TO_MS)

        plot_specs.append(
            make_plot_spec(f"plot-{index}", title, labels, means_ms, errors_ms)
        )

    page_title = f"benchmark results at {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"
    output_path = Path(OUTPUT_FILE)
    output_path.write_text(build_html(plot_specs, page_title), encoding="utf-8")
    print(f"Wrote {output_path}")
    open_in_browser(output_path.resolve())


if __name__ == "__main__":
    main()
